?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta property="og:title" content="<?=e($s['title'])?>"><meta property="og:description" content="<?=e($s['category']?:$lang['label'])?>"><title><?=e($s['title'])?> — PocketCat Code</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/themes/prism.min.css"><style>body{font-family:system-ui;margin:0;background:#f5f7fb;color:#182033}.wrap{max-width:1100px;margin:28px auto;padding:16px}.card{background:#fff;border:1px solid #e4e8f0;border-radius:18px;padding:22px;box-shadow:0 12px 35px #15223a0b}.meta{display:flex;gap:8px;flex-wrap:wrap;color:#657086;font-size:13px}.tag{padding:4px 8px;border-radius:999px;background:#eef2ff;color:#4f46b8}.code{overflow:auto;border-radius:14px;background:#fff}.code pre{margin:0;padding:18px;min-height:200px}.top{display:flex;justify-content:space-between;gap:14px;align-items:flex-start;flex-wrap:wrap}.actions{display:flex;gap:8px;flex-wrap:wrap}.btn{display:inline-block;border:0;border-radius:10px;padding:10px 14px;background:#6557e8;color:#fff;text-decoration:none;font-weight:700;cursor:pointer}.muted{color:#68758a}.dark{background:#0b1020;color:#e7ecf7}.dark .card{background:#141b2f;border-color:#27314a}.dark .code{background:#0f172a}.dark .meta,.dark .muted{color:#aab4c9}</style></head><body><div class="wrap"><section class="card"><div class="top"><div><div class="muted">PocketCat Code</div><h1><?=e($s['title'])?></h1><div class="meta"><span><?=e($lang['label'])?></span><?php if($s['category']):?><span>• <?=e($s['category'])?></span><?php endif;?><span>• <?=number_format((int)$s['views'])?> views</span><?php if($s['published_at']):?><span>• Published <?=e($s['published_at'])?></span><?php endif;?></div><?php if($tags):?><div class="meta" style="margin-top:8px"><?php foreach($tags as $t):?><span class="tag">#<?=e($t)?></span><?php endforeach;?></div><?php endif;?></div><div class="actions"><button class="btn" id="theme">☾ Theme</button><button class="btn" id="copy">Copy</button><a class="btn" href="/qr/code-<?=e($s['token'])?>" target="_blank">QR</a></div></div><p class="muted"><?=e($s['author_country']?:'')?><?=($s['author_city']?', '.e($s['author_city']):'')?><?=($s['expires_at']?' · Expires '.e($s['expires_at']):'')?></p><div class="code"><pre><code class="language-<?=e($lang['prism'])?>" id="source"><?=e($s['code_text'])?></code></pre></div></section></div><script src="https://cdnjs.cloudflare.com/ajax/libs/prism/1.29.0/prism.min.js"></script><script>const raw=<?=json_encode($s['code_text'])?>;if(window.Prism)Prism.highlightElement(document.getElementById('source'));document.getElementById('copy').onclick=async()=>{await navigator.clipboard.writeText(raw);document.getElementById('copy').textContent='Copied';setTimeout(()=>document.getElementById('copy').textContent='Copy',1200)};document.getElementById('theme').onclick=()=>document.body.classList.toggle('dark');</script></body></html>